import kotlin.math.min

fun main() {
    val (n , m) = readLine()!!.split(' ').map(String::toInt)
    println(doIt(n, m))
}

fun doIt(n: Int, m: Int): Int {
    return if (m == 0) 1 else min(m, n - m)
}
